import{_ as p,a0 as l,w as o,s as r,ao as h,I as n,x as i,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Git 系列（四）：在 Git 中進行版本回退 | LCTT x X-CMD","titleTemplate":false,"description":"Git 系列（四）：在 Git 中進行版本回退 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 系列（四）：在 Git 中進行版本回退 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 系列（四）：在 Git 中進行版本回退 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160726 How to restore older file versions in Git","title":"Git 系列（四）：在 Git 中進行版本回退","tag":"201608","desc":""},"relativePath":"201608/20160726 How to restore older file versions in Git.md","filePath":"[post].md"}'),g={name:"201608/20160726 How to restore older file versions in Git.md"};function d(c,s,k,b,u,f){const a=l("Link");return o(),r("div",null,[s[13]||(s[13]=h(`<h1 id="git-系列-四-在-git-中進行版本回退" tabindex="-1">Git 系列（四）：在 Git 中進行版本回退 <a class="header-anchor" href="#git-系列-四-在-git-中進行版本回退" aria-label="Permalink to “Git 系列（四）：在 Git 中進行版本回退”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/file_system.jpg?itok=s2b60oIB" alt=""></p><p>在這篇文章中，你將學到如何查看項目中的歷史版本，如何進行版本回退，以及如何創建 Git 分支以便你可以大膽嘗試而不會出現問題。</p><p>在你的 Git 項目的歷史中，你的位置就像是搖滾專輯中的一個片段，由一個被稱為 HEAD 的 標記來確定（如磁帶錄音機或錄音播放器的播放頭）。要在你的 Git 時間線上前後移動 HEAD ，需要使用 <code>git checkout</code> 命令。</p><p>git checkout 命令的使用方式有兩種。最常見的用途是從一個以前的提交中恢復文件，你也可以整個倒回磁帶，切換到另一個分支。</p><h3 id="恢復一個文件" tabindex="-1">恢復一個文件 <a class="header-anchor" href="#恢復一個文件" aria-label="Permalink to “恢復一個文件”">​</a></h3><p>當你意識到一個本來很好文件被你完全改亂了。我們都這麼幹過：我們把文件放到一個地方，添加並提交，然後我們發現它還需要做點最後的調整，最後這個文件被搞得面目全非了。</p><p>要把它恢復到最後的完好狀態，使用 git checkout 從最後的提交（即 HEAD）中恢復：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout HEAD filename</span></span></code></pre></div><p>如果你碰巧提交了一個錯誤的版本，你需要找回更早的版本，使用 git log 查看你更早的提交，然後從合適的提交中找回它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>79a4e5f bad take</span></span>
<span class="line"><span>f449007 The second commit</span></span>
<span class="line"><span>55df4c2 My great project, first commit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git checkout 55df4c2 filename</span></span></code></pre></div><p>現在，以前的文件恢復到了你當前的位置。（任何時候你都可以用 git status 命令查看你的當前狀態）因為這個文件改變了，你需要添加這個文件，再進行提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add filename</span></span>
<span class="line"><span>$ git commit -m &#39;restoring filename from first commit.&#39;</span></span></code></pre></div><p>使用 Git log 驗證你所提交的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>d512580 restoring filename from first commit</span></span>
<span class="line"><span>79a4e5f bad take</span></span>
<span class="line"><span>f449007 The second commit</span></span>
<span class="line"><span>55df4c2 My great project, first commit.</span></span></code></pre></div><p>從本質上講，你已經倒好了磁帶並修復了壞的地方，所以你需要重新錄製正確的。</p><h3 id="回退時間線" tabindex="-1">回退時間線 <a class="header-anchor" href="#回退時間線" aria-label="Permalink to “回退時間線”">​</a></h3><p>恢復文件的另一種方式是回退整個 Git 項目。這裏使用了分支的思想，這是另一種替代方法。</p><p>如果你要回到歷史提交，你要將 Git HEAD 回退到以前的版本才行。這個例子將回到最初的提交處：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>d512580 restoring filename from first commit</span></span>
<span class="line"><span>79a4e5f bad take</span></span>
<span class="line"><span>f449007 The second commit</span></span>
<span class="line"><span>55df4c2 My great project, first commit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git checkout 55df4c2</span></span></code></pre></div><p>當你以這種方式倒回磁帶，如果你按下錄音鍵再次開始，就會丟失以前的工作。Git 默認假定你不想這樣做，所以將 HEAD 從項目中分離出來，可以讓你如所需的那樣工作，而不會因為偶爾的記錄而影響之後的工作。</p><p>如果你想看看以前的版本，想要重新做或者嘗試不同的方法，那麼安全一點的方式就是創建一個新的分支。可以將這個過程想像為嘗試同一首歌曲的不同版本，或者創建一個混音的。原始的依然存在，關閉那個分支做你想做的版本吧。</p><p>就像記錄到一個空白磁帶一樣，把你的 Git HEAD 指到一個新的分支處：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout -b remix</span></span>
<span class="line"><span>Switched to a new branch &#39;remix&#39;</span></span></code></pre></div><p>現在你已經切換到了另一個分支，在你面前的是一個替代的乾淨工作區，準備開始工作吧。</p><p>也可以不用改變時間線來做同樣的事情。也許你很想這麼做，但切換到一個臨時的工作區只是為了嘗試一些瘋狂的想法。這在工作中完全是可以接受的，請看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>nothing to commit, working directory clean</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ git checkout -b crazy_idea</span></span>
<span class="line"><span>Switched to a new branch &#39;crazy_idea&#39;</span></span></code></pre></div><p>現在你有一個乾淨的工作空間，在這裏你可以完成一些奇怪的想法。一旦你完成了，可以保留你的改變，或者丟棄他們，並切換回你的主分支。</p><p>若要放棄你的想法，切換到你的主分支，假裝新分支不存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout master</span></span></code></pre></div><p>想要繼續使用你的瘋狂的想法，需要把它們拉回到主分支，切換到主分支然後合併新分支到主分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout master</span></span>
<span class="line"><span>$ git merge crazy_idea</span></span></code></pre></div><p>git 的分支功能很強大，開發人員在克隆倉庫後馬上創建一個新分支是很常見的做法；這樣，他們所有的工作都在自己的分支上，可以提交併合併到主分支。Git 是很靈活的，所以沒有“正確”或“錯誤”的方式（甚至一個主分支也可以與其所屬的遠程倉庫分離），但分支易於分離任務和提交貢獻。不要太激動，你可以如你所願的有很多的 Git 分支。完全自由。</p><h3 id="遠程協作" tabindex="-1">遠程協作 <a class="header-anchor" href="#遠程協作" aria-label="Permalink to “遠程協作”">​</a></h3><p>到目前為止你已經在自己舒適而私密的家中維護着一個 Git 倉庫，但如何與其他人協同工作呢？</p><p>有好幾種不同的方式來設置 Git 以便讓多人可以同時在一個項目上工作，所以首先我們要克隆倉庫，你可能已經從某人的 Git 服務器或 GitHub 主頁，或在局域網中的共享存儲上克隆了一個倉庫。</p><p>工作在私人倉庫下和共享倉庫下唯一不同的是你需要把你的改變 <code>push</code> 到別人的倉庫。我們把工作的倉庫稱之為本地（local）倉庫，其他倉庫稱為遠程（remote）倉庫。</p><p>當你以讀寫的方式克隆一個倉庫時，克隆的倉庫會繼承自被稱為 origin 的遠程庫。你可以看看你的克隆倉庫的遠程倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote --verbose</span></span>
<span class="line"><span>origin  seth@example.com:~/myproject.Git (fetch)</span></span>
<span class="line"><span>origin  seth@example.com:~/myproject.Git (push)</span></span></code></pre></div><p>有一個 origin 遠程庫非常有用，因為它有異地備份的功能，並允許其他人在該項目上工作。</p><p>如果克隆沒有繼承 origin 遠程庫，或者如果你選擇以後再添加，可以使用 <code>git remote</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add seth@example.com:~/myproject.Git</span></span></code></pre></div><p>如果你修改了文件，想把它們發到有讀寫權限的 origin 遠程庫，使用 <code>git push</code>。第一次推送改變，必須也發送分支信息。不直接在主分支上工作是一個很好的做法，除非你被要求這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout -b seth-dev</span></span>
<span class="line"><span>$ git add exciting-new-file.txt</span></span>
<span class="line"><span>$ git commit -m &#39;first push to remote&#39;</span></span>
<span class="line"><span>$ git push -u origin HEAD</span></span></code></pre></div><p>它會推送你當前的位置（HEAD）及其存在的分支到遠程。當推送過一次後，以後每次推送可以不使用 -u 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add another-file.txt</span></span>
<span class="line"><span>$ git commit -m &#39;another push to remote&#39;</span></span>
<span class="line"><span>$ git push origin HEAD</span></span></code></pre></div><h3 id="合併分支" tabindex="-1">合併分支 <a class="header-anchor" href="#合併分支" aria-label="Permalink to “合併分支”">​</a></h3><p>當你工作在一個 Git 倉庫時，你可以合併任意測試分支到主分支。當團隊協作時，你可能想在將它們合併到主分支之前檢查他們的改變：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout contributor</span></span>
<span class="line"><span>$ git pull</span></span>
<span class="line"><span>$ less blah.txt  ### 檢查改變的文件</span></span>
<span class="line"><span>$ git checkout master</span></span>
<span class="line"><span>$ git merge contributor</span></span></code></pre></div><p>如果你正在使用 GitHub 或 GitLab 以及類似的東西，這個過程是不同的。但克隆項目並把它作為你自己的倉庫都是相似的。你可以在本地工作，將改變提交到你的 GitHub 或 GitLab 帳户，而不用其它人的許可，因為這些庫是你自己的。</p><p>如果你想要讓你克隆的倉庫接受你的改變，需要創建了一個拉取請求（pull request），它使用 Web 服務的後端發送補丁到真正的擁有者，並允許他們審查和拉取你的改變。</p><p>克隆一個項目通常是在 Web 服務端完成的，它和使用 Git 命令來管理項目是類似的，甚至推送的過程也是。然後它返回到 Web 服務打開一個拉取請求，工作就完成了。</p><p>下一部分我們將整合一些有用的插件到 Git 中來幫你輕鬆的完成日常工作。</p><hr>`,54)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://opensource.com/life/16/7/how-restore-older-file-versions-git"},{default:t(()=>[...s[0]||(s[0]=[i("https://opensource.com/life/16/7/how-restore-older-file-versions-git",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[2]||(s[2]=[i("Seth Kenlon",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),e(a,{href:"https://github.com/strugglingyouth"},{default:t(()=>[...s[3]||(s[3]=[i("strugglingyouth",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const G=p(g,[["render",d]]);export{C as __pageData,G as default};
